for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: mixed board policy descriptions identify the role they govern`, () => {
    const roles = [
      Role.WolfKing,
      Role.Hunter,
      Role.Gargoyle,
      Role.Psychic,
