    second.world.getComponent(5, COMPONENT.Role)!.privateState as Record<
      string,
      unknown
    >
  ).hiddenTest = "PRIVATE_OPPONENT_STATE";
  // 未发表的状态变化不能被观察适配器提升为公开知识。
